// ORION run-event contract v1.2 (orion/contracts/README.md in the sandbox repo).
// Hand-written: no AG-UI package is in the lockfile. Mirrors orion/agent/orion_agent/models.py;
// change both together. The fixtures in __fixtures__ are generated by
// orion/contracts/fixtures/build_fixtures.py and copied here byte for byte.

export const CONTRACT_VERSION = '1.2';

export const RUN_STATUSES = [
  'Planning',
  'Clarifying',
  'AwaitingConsent',
  'Executing',
  'AwaitingConfirmation',
  'Stopping',
  'Answering',
  'Complete',
  'Partial',
  'Limited',
  'Unsupported',
  'ObservedOnly',
  'Cancelled',
  'Failed',
  'Interrupted',
] as const;
export type RunStatus = (typeof RUN_STATUSES)[number];

export const STEP_STATUSES = [
  'Queued',
  'AwaitingUser',
  'Running',
  'Retrying',
  'Done',
  'Empty',
  'Failed',
  'Skipped',
  'Reused',
] as const;
export type StepStatus = (typeof STEP_STATUSES)[number];

/** Statuses a run pauses in; the next turn resumes it. */
export const WAITING_STATUSES = [
  'Clarifying',
  'AwaitingConsent',
  'AwaitingConfirmation',
] as const satisfies readonly RunStatus[];
export type WaitingStatus = (typeof WAITING_STATUSES)[number];

export const END_STATUSES = [
  'Complete',
  'Partial',
  'Limited',
  'Unsupported',
  'ObservedOnly',
  'Cancelled',
  'Failed',
  'Interrupted',
] as const satisfies readonly RunStatus[];
export type EndStatus = (typeof END_STATUSES)[number];

/**
 * Statuses whose record holds a lease. Once it lapses the view route shows the run Cancelled
 * (it was Stopping) or Interrupted (any other), as of `lease.expiresAt`.
 */
export const LEASED_STATUSES = ['Planning', 'Executing', 'Answering', 'Stopping'] as const satisfies readonly RunStatus[];

/** Leased statuses whose lease is renewed every 30 s (180 s expiry); a Stopping lease lapses after STOP_LEASE_S. */
export const RENEWED_STATUSES = ['Planning', 'Executing', 'Answering'] as const satisfies readonly RunStatus[];
export const STOP_LEASE_S = 30;

/**
 * RUN_FINISHED never carries Failed (RUN_ERROR does). It carries Interrupted only when the
 * turn targeted a run whose lease expired.
 */
export type FinishedStatus = WaitingStatus | Exclude<EndStatus, 'Failed'>;

/** Not run statuses: `warmup` ends Warmed, a standalone `viz_report` ends Recorded. */
export type TurnOnlyStatus = 'Warmed' | 'Recorded';

export const LIMITATION_CODES = [
  'NAMED_TOOL_MISMATCH',
  'OUT_OF_PANEL',
  'INELIGIBLE_GROUP',
  'TOOL_FAILED',
  'MODEL_DECLINED',
  'PLANNER_DECLINED',
  'UNSUPPORTED_ANALYSIS',
  'CLINICAL_ADVICE',
  'OUT_OF_SCOPE',
  'EMPTY_COHORT',
  'WRITE_SKIPPED',
  'RUN_INTERRUPTED',
  'WRITE_VERIFY_FAILED',
  'VIEWER_P_ROUNDED',
  'UNSUPPORTED_FIELD',
  'UNKNOWN_FIELD',
  'UNKNOWN_VALUE',
  // v1.2: guard and coverage codes.
  'AMBIGUOUS_REQUEST',
  'TOO_MANY_IDS',
  'NOT_SUBSET',
  'FEWER_THAN_N',
  'TIES_AT_CUTOFF',
  'PANEL_COVERAGE',
  'STAT_UNAVAILABLE',
  'REQUEST_TOO_LARGE',
  'CALL_BUDGET',
  'KG_NOT_CONNECTED',
] as const;
export type LimitationCode = (typeof LIMITATION_CODES)[number];

export const CONTROLLER_CODES = [
  'INVALID_INPUT',
  'NOT_IMPLEMENTED',
  'RUN_BUSY',
  'RUN_NOT_FOUND',
  'STALE_ACTION',
  'INTERNAL_ERROR',
] as const;
export type ControllerCode = (typeof CONTROLLER_CODES)[number];

/** RUN_ERROR codes that reject a turn: no run is created and no run's status changes. */
export const REJECTION_CODES = [
  'INVALID_INPUT',
  'RUN_BUSY',
  'RUN_NOT_FOUND',
  'NOT_IMPLEMENTED',
  'STALE_ACTION',
] as const satisfies readonly ControllerCode[];
export type RejectionCode = (typeof REJECTION_CODES)[number];

export type OrionCode = LimitationCode | ControllerCode;

/** The 15 `appId` values of config/gen3/analysisTools.json, before the Assistant entry. */
export const APP_IDS = [
  'Projects',
  'CohortBuilder',
  'Repository',
  'MutationFrequency',
  'cDave',
  'CohortComparison',
  'Correlation',
  'GB',
  'ProteinPaint',
  'OncoMatrix',
  'GeneExpression',
  'DE',
  'SC',
  'Umap',
  'SetOperations',
] as const;
export type AppId = (typeof APP_IDS)[number];

/** The four analysis kinds the compiler can run; follow-up chips name one. */
export const ANALYSIS_KINDS = [
  'survival_compare',
  'top_mutated_genes',
  'differential_expression',
  'cohort_size',
] as const;
export type AnalysisKind = (typeof ANALYSIS_KINDS)[number];

export const VERIFIER_RULES = ['V-NUM', 'V-REF', 'V-ENT', 'V-SEC', 'V-COMP', 'V-LIM'] as const;
export type VerifierRule = (typeof VERIFIER_RULES)[number];

/** Every answer and limitation card ends with it; the snapshot's `notice` carries the deployment's text. */
export const SYNTHETIC_NOTICE = 'Synthetic sandbox — all data is fabricated and has no clinical meaning.';

/** Every frame, a snapshot included, is at most this many bytes. */
export const SNAPSHOT_LIMIT_BYTES = 32 * 1024;

/** TOOL_CALL_ARGS and TEXT_MESSAGE_CONTENT deltas are at most this many characters. */
export const DELTA_CHUNK_CHARS = 8 * 1024;

/** A view shows at most this many ranked rows in all; the rest are in the record's calls. */
export const VIEW_RANK_CAP = 20;
/** A frozen table shows at most this many rows. */
export const FROZEN_ROWS_CAP = 10;
/** topN bounds: DE top_n and top mutated genes n. */
export const MAX_TOP_N_DE = 100;
export const MAX_TOP_N_GENES = 50;

// ---------------------------------------------------------------- RunView

export type ScopeSource =
  | 'all_cases'
  | 'active_cohort'
  | 'saved_cohort'
  | 'thread_cohort';

export interface PlanScope {
  source: ScopeSource;
  name: string;
  /** Null until a count is known: the browser sent none and no step has sized the scope yet. */
  caseCount: number | null;
}

export interface PlanRow {
  row: number;
  label: string;
  tool: string;
  reason: string;
  stepIds: string[];
}

export interface Assumption {
  code: string;
  text: string;
}

/** A scope the plan can switch to; also the value of an `edit_plan` scope edit. Omit absent keys. */
export interface ScopeChoice {
  source: ScopeSource;
  cohortName?: string;
  ledgerRef?: string;
}

export type DeMethod = 'wilcoxon' | 'edgeR' | 'limma';

/** The thresholds a DE answer reports (C-DEFAULTS: adjusted p < 0.05, |log2FC| > 0.3). */
export interface DeThresholds {
  /** 0 < x <= 1. */
  pValueCutoff: number;
  pValueType: 'adjusted' | 'original';
  /** >= 0. */
  foldChangeCutoff: number;
}

export type EditField = 'scope' | 'method' | 'topN' | 'thresholds' | 'cohortName';

/** A setting the plan card can edit, with its current value; sending it back changes nothing. */
export type Editable =
  | { field: 'scope'; label: string; value: ScopeChoice }
  | { field: 'method'; label: string; value: DeMethod }
  | { field: 'topN'; label: string; value: number; /** 100 for DE, 50 for top mutated genes. */ max: number }
  | { field: 'thresholds'; label: string; value: DeThresholds }
  | { field: 'cohortName'; label: string; value: string; ref: string };

export interface Plan {
  version: number;
  signature: string;
  scope: PlanScope;
  rows: PlanRow[];
  assumptions: Assumption[];
  writes: boolean;
  paraphrase: string;
  /** The second scope a follow-up names after a cohort switch (E15); the chip switches to it. */
  altScope: PlanScope | null;
  /** The scope edit value for altScope: the chip sends {field: 'scope', value: altScopeChoice}. Both or neither. */
  altScopeChoice: ScopeChoice | null;
  editable: Editable[];
}

export type StepKind = 'server' | 'exec' | 'client';

/** The plan version and step whose calls produced a Reused step's result. */
export interface StepOrigin {
  planVersion: number;
  stepId: string;
}

export interface Step {
  id: string;
  row: number;
  tool: string;
  kind: StepKind;
  status: StepStatus;
  folded: boolean;
  inputSummary: string;
  outputSummary: string | null;
  durationMs: number | null;
  code: OrionCode | null;
  /** Set exactly when the step is Reused; its calls are the record's calls of that version and step. */
  reusedFrom: StepOrigin | null;
}

export interface Fact {
  /** Also its placeholder in model text, such as `{{f.s10.top.1.gene}}`. */
  id: string;
  label: string;
  /** A number, or a string for gene symbols and other names model text cites by placeholder. */
  value: number | string;
  unit: string;
  stepId: string;
  row: number;
  tool: string;
  jsonPointer: string;
}

/** A segment with `factId` is a number or name that renders with its citation chip. */
export interface Segment {
  text: string;
  factId?: string;
}

export interface Sentence {
  segments: Segment[];
  /** Set when the verifier dropped the sentence: segments is empty and the card shows a marker. */
  dropped?: VerifierRule;
  /** The facts a kept Interpretation or Hypotheses sentence cites (V-REF); absent on Observed. */
  cites?: string[];
}

/** A catalog app that can take the question further, as the catalog names it. */
export interface NearestApp {
  appId: AppId;
  title: string;
}

/** An "Open <app>" link under Hypotheses and next steps. */
export type OpenLink = NearestApp;

export interface Limitation {
  code: OrionCode;
  /** Plain text, for TEXT_MESSAGE and for a line that names no tool-returned number. */
  text: string;
  unblock: string | null;
  /** Empty when no app applies. */
  nearestApps: NearestApp[];
  /** The same line with chips, present exactly when it names a tool-returned number; render it instead of text. */
  segments?: Segment[];
}

/** A follow-up chip: a click asks `question` as a new turn. Label up to 60, question up to 200 characters. */
export interface FollowUp {
  label: string;
  question: string;
  kind: AnalysisKind;
}

// ------------------------------------------------ Cohort definitions (defSha256)

export const COHORT_DEF_SCHEMA = 'orion.cohort-def/v1';

export interface CaseIdsDefinition {
  kind: 'case_ids';
  caseIds: string[];
}

export type ClauseOp = 'in' | '!=' | '>' | '>=' | '<' | '<=';

export interface FilterClause {
  field: string;
  op: ClauseOp;
  /** All strings or all numbers; exactly one unless op is `in`. */
  values: (string | number)[];
}

export interface FilterDefinition {
  kind: 'filter';
  clauses: FilterClause[];
}

/** A cohort's canonical definition; defSha256 hashes its normalized canonical JSON. */
export type CanonicalDefinition = CaseIdsDefinition | FilterDefinition;

// ------------------------------------------------------- Pinned viz inputs
// The inputs a viz card mounts, as the snapshot carries them. ProteinPaint's launcher
// arguments are built from these in viz/ppPinnedArgs.ts.

export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

/** A Gen3 GQL case filter as the wrappers send it, e.g. `{"and":[{"in":{"case_id":[...]}}]}`. */
export type GqlFilter = { [operator: string]: JsonValue };

/** A DE group as ProteinPaint integer sample ids (the sandbox maps case n to sample n). */
export interface SampleGroup {
  name: string;
  sampleIds: readonly number[];
}

/** A DEinput group seeded from a saved cohort, as ProteinPaint's Cohort picker builds it. */
export interface CohortGroup {
  name: string;
  cohortId: string;
  filter0: GqlFilter;
}

/** Volcano settings a DE card may pin besides the method (ProteinPaint 2.216.0 setting keys). */
export interface VolcanoPins {
  foldChangeCutoff?: number;
  /** -log10 cutoff. */
  pValue?: number;
  pValueType?: 'adjusted' | 'original';
  /** Declared in 2.216.0's defaults but read by nothing; pinned only to probe Open question 9. */
  rankBy?: string;
}

export type PinnedViz =
  | { kind: 'survival'; filter0: GqlFilter | null; term: string; overlay: string }
  | { kind: 'oncomatrix'; filter0: GqlFilter | null; genes: readonly string[] }
  | {
      kind: 'deDirect';
      /** Control first: fold change is log2(groups[1] / groups[0]). */
      groups: [SampleGroup, SampleGroup];
      method: DeMethod;
      volcano?: VolcanoPins;
    }
  | { kind: 'deInput'; groups: [CohortGroup, CohortGroup] };

export type PinnedKind = PinnedViz['kind'];

/** The cited output a card shows once it is no longer one of the two live cards. */
export interface FrozenTable {
  /** 1 to 8 columns. */
  columns: string[];
  /** At most FROZEN_ROWS_CAP (10) rows, one cell per column; a cell with factId renders a chip. */
  rows: Segment[][];
  /** Segments, so a tool-returned number in the note carries its chip. */
  note: Segment[] | null;
}

export interface VizSpec {
  vizId: string;
  appId: AppId;
  /** Always equals `pinned.kind`. */
  launcher: PinnedKind;
  citesSteps: string[];
  /** Null only in a snapshot trimmed to fit 32 KB: read the spec from the view route before mounting. */
  pinned: PinnedViz | null;
  /** sha256 of the canonical pinned document (viz/ppPinnedArgs.ts `pinnedHash`). */
  pinnedHash: string;
  title: string;
  /** One line under the chart, such as the DE sort caption or the J1 rounding footnote. */
  caption: string | null;
  /**
   * pinnedHash of the pinned form derived from the cited step's actual request. The parity
   * badge shows a match only when the browser's recomputed pinnedHash equals this and pinnedHash.
   */
  requestPinnedHash: string;
  frozen: FrozenTable | null;
  /** The run cohorts (RunView.cohorts refs) the card is pinned to; hand-off opens on their cohortId. */
  cohortRefs: string[];
}

// ---------------------------------------------------- Run cohorts and pauses

export type CohortRole = 'scope' | 'planned';
export type CohortSource = 'planned' | ScopeSource;
export type CohortSave = 'none' | 'proposed' | 'saved' | 'reused' | 'skipped';

/** One cohort of the run: its scope (ref `base`) or a cohort the plan builds. */
export interface CohortView {
  ref: string;
  role: CohortRole;
  source: CohortSource;
  name: string;
  definitionText: string;
  /** Null until the definition is known: a case-ID cohort is known once its step finishes. */
  defSha256: string | null;
  caseCount: number | null;
  save: CohortSave;
  /**
   * The platform cohort hand-off opens. For `base`: the active cohort's id (null when unsaved),
   * the matched saved cohort's id or the ledger cohort's id; null for all cases. For a planned
   * cohort: the read-back id once saved or reused. Null opens the tool with no cohort switch.
   */
  cohortId: string | null;
  savedName: string | null;
  /** The fact behind caseCount once a step sized the cohort; the scope line cites the base cohort's. */
  caseCountFactId: string | null;
}

export interface CohortReuse {
  cohortId: string;
  name: string;
}

export interface PendingCohort {
  ref: string;
  name: string;
  definitionText: string;
  /** Null only in a snapshot that dropped it to fit 32 KB; save_cohorts args and the record always carry it. */
  definition: CanonicalDefinition | null;
  defSha256: string;
  caseCount: number;
  /** RNA-seq eligible samples, when the plan checked eligibility. */
  eligibleCount: number | null;
  /** The agent's reuse match from the turn's cohort context; the browser re-checks at Create. */
  reuse: CohortReuse | null;
  /** The facts behind the card's two counts: every count on the confirmation card is a chip. */
  caseCountFactId: string | null;
  eligibleCountFactId: string | null;
}

export type ClarifySlot = 'split_term' | 'cohort_field' | 'gene' | 'scope';

export interface ClarifyOption {
  optionId: string;
  /** The vocabulary field the option names, or null for an option that is not a field. */
  field: string | null;
  label: string;
  preview: string;
}

export interface ClarifyPending {
  kind: 'clarify';
  slot: ClarifySlot;
  question: string;
  /** 2 to 5 options. */
  options: ClarifyOption[];
}

export interface ConsentPending {
  kind: 'consent';
  named: NearestApp;
  proposed: NearestApp;
  reason: string;
}

export interface ConfirmPending {
  kind: 'confirm';
  nonce: string;
  planSignature: string;
  planVersion: number;
  /** The write step, such as s8. */
  stepId: string;
  cohorts: PendingCohort[];
}

/** The `save_cohorts` TOOL_CALL_ARGS JSON: the confirm payload with every definition present. */
export interface SaveCohortsArgs extends ConfirmPending {
  cohorts: (PendingCohort & { definition: CanonicalDefinition })[];
}

/** Non-null exactly while the run waits: Clarifying, AwaitingConsent, AwaitingConfirmation. */
export type Pending = ClarifyPending | ConsentPending | ConfirmPending;

export const PENDING_KIND_BY_STATUS = {
  Clarifying: 'clarify',
  AwaitingConsent: 'consent',
  AwaitingConfirmation: 'confirm',
} as const satisfies Record<WaitingStatus, Pending['kind']>;

/** Where the run ran. In mode H the viz card compares the local fingerprint and freezes on a mismatch. */
export interface ViewEnvironment {
  mode: 'L' | 'A' | 'H';
  /** The s1 fixture fingerprint (orion.fixture-fingerprint/v1), null until s1 ran. */
  fingerprintSha256: string | null;
}

export const FINGERPRINT_SCHEMA = 'orion.fixture-fingerprint/v1';

/** An earlier plan version an edit replaced. */
export interface SupersededSummary {
  planVersion: number;
  at: string;
  /** The run status when the edit replaced it. */
  status: RunStatus;
  /** Whether that version had an answer the card now marks superseded. */
  hadAnswer: boolean;
}

export interface RunView {
  schema: 'orion.run-view/v1';
  threadId: string;
  runId: string;
  revision: number;
  status: RunStatus;
  code: OrionCode | null;
  question: string;
  updatedAt: string;
  plan: Plan | null;
  steps: Step[];
  facts: Fact[];
  observed: Sentence[];
  limitations: Limitation[];
  /** Verified model text with placeholders already resolved into segments; null until it passes. */
  interpretation: Sentence[] | null;
  hypotheses: Sentence[] | null;
  withheldReason: string | null;
  vizSpecs: VizSpec[];
  pending: Pending | null;
  cohorts: CohortView[];
  followUps: FollowUp[];
  openLinks: OpenLink[];
  superseded: SupersededSummary[];
  notice: string;
  environment: ViewEnvironment;
}

// ----------------------------------------------------------------- Events

export interface RunStartedEvent {
  type: 'RUN_STARTED';
  threadId: string;
  runId: string;
}

export interface StateSnapshotEvent {
  type: 'STATE_SNAPSHOT';
  snapshot: RunView;
}

export interface StepStartedEvent {
  type: 'STEP_STARTED';
  stepName: string;
}

export interface StepFinishedEvent {
  type: 'STEP_FINISHED';
  stepName: string;
}

/** Sent at the confirmation pause; `toolCallId` equals the pending nonce. */
export interface ToolCallStartEvent {
  type: 'TOOL_CALL_START';
  toolCallId: string;
  toolCallName: 'save_cohorts';
}

/** Deltas of at most 8,192 characters; their concatenation is the SaveCohortsArgs JSON. */
export interface ToolCallArgsEvent {
  type: 'TOOL_CALL_ARGS';
  toolCallId: string;
  delta: string;
}

export interface ToolCallEndEvent {
  type: 'TOOL_CALL_END';
  toolCallId: string;
}

export interface TextMessageStartEvent {
  type: 'TEXT_MESSAGE_START';
  messageId: string;
  role: 'assistant';
}

export interface TextMessageContentEvent {
  type: 'TEXT_MESSAGE_CONTENT';
  messageId: string;
  delta: string;
}

export interface TextMessageEndEvent {
  type: 'TEXT_MESSAGE_END';
  messageId: string;
}

export interface HeartbeatEvent {
  type: 'CUSTOM';
  name: 'orion.heartbeat';
  value: { ts: string };
}

export interface RunFinishedEvent {
  type: 'RUN_FINISHED';
  threadId: string;
  runId: string;
  result: { status: FinishedStatus | TurnOnlyStatus; code: OrionCode | null };
}

/** Carries no ids: it belongs to the run whose invocation is open. */
export interface RunErrorEvent {
  type: 'RUN_ERROR';
  message: string;
  code: OrionCode;
}

export type AguiEvent =
  | RunStartedEvent
  | StateSnapshotEvent
  | StepStartedEvent
  | StepFinishedEvent
  | ToolCallStartEvent
  | ToolCallArgsEvent
  | ToolCallEndEvent
  | TextMessageStartEvent
  | TextMessageContentEvent
  | TextMessageEndEvent
  | HeartbeatEvent
  | RunFinishedEvent
  | RunErrorEvent;

export type AguiEventType = AguiEvent['type'];

export const AGUI_EVENT_TYPES = [
  'RUN_STARTED',
  'STATE_SNAPSHOT',
  'STEP_STARTED',
  'STEP_FINISHED',
  'TOOL_CALL_START',
  'TOOL_CALL_ARGS',
  'TOOL_CALL_END',
  'TEXT_MESSAGE_START',
  'TEXT_MESSAGE_CONTENT',
  'TEXT_MESSAGE_END',
  'CUSTOM',
  'RUN_FINISHED',
  'RUN_ERROR',
] as const satisfies readonly AguiEventType[];

// ---------------------------------------------------------------- Request

export interface WireFilterSet {
  mode: 'and' | 'or';
  root: Record<string, unknown>;
}

export interface CohortSnapshot {
  id: string | null;
  name: string;
  filters: WireFilterSet;
  /** null until the platform has counted the cohort. */
  caseCount: number | null;
}

export interface SavedCohortSnapshot extends CohortSnapshot {
  id: string;
}

export interface CohortContext {
  active: CohortSnapshot;
  saved: SavedCohortSnapshot[];
}

/** One pending cohort after Create, read back from the cohort store. */
export interface SavedCohortReadBack {
  ref: string;
  cohortId: string;
  name: string;
  /** defSha256 the browser computed from the saved cohort's stored filters, as read back. */
  defSha256: string;
  /** True when an identical saved cohort was reused instead of created. */
  reused: boolean;
}

/** Whether a viz card mounted; reports ride on the next turn's `vizReports`. */
export interface VizReport {
  runId: string;
  vizId: string;
  mounted: boolean;
  error: string | null;
  /** True when the recomputed pinnedHash equals pinnedHash and requestPinnedHash; null if not checked. */
  pinnedHashVerified: boolean | null;
}

/** Every action may carry up to 8 queued viz reports, for any run of the thread. */
export interface ActionBase {
  vizReports?: VizReport[];
}

export type EditPlanAction =
  | { action: 'edit_plan'; field: 'scope'; value: ScopeChoice; cohortContext: CohortContext }
  | { action: 'edit_plan'; field: 'method'; value: DeMethod }
  | { action: 'edit_plan'; field: 'topN'; value: number }
  | { action: 'edit_plan'; field: 'thresholds'; value: DeThresholds }
  | { action: 'edit_plan'; field: 'cohortName'; value: string; ref: string };

export type OrionAction = ActionBase &
  (
    | { action: 'warmup' }
    | {
        action: 'ask';
        question: string;
        cohortContext: CohortContext;
        /** The paused run the researcher chose to cancel before this question runs. */
        cancelWaiting?: string;
      }
    | { action: 'cancel' }
    | { action: 'clarify_answer'; optionId: string }
    | { action: 'consent'; accept: boolean }
    | {
        action: 'confirm';
        nonce: string;
        decision: 'create' | 'dont_save';
        /** Every pending cohort for create; empty for dont_save. */
        saved: SavedCohortReadBack[];
        /** The ref the researcher ticked make-active for, or null. */
        makeActive: string | null;
      }
    | EditPlanAction
    | { action: 'retry_step'; stepId: string }
    | {
        action: 'viz_report';
        vizId: string;
        mounted: boolean;
        error: string | null;
        pinnedHashVerified: boolean | null;
      }
  );

export type OrionActionName = OrionAction['action'];

/** The run statuses in which each action applies to its run; otherwise STALE_ACTION. */
export const ACTION_STATUSES = {
  clarify_answer: ['Clarifying'],
  consent: ['AwaitingConsent'],
  confirm: ['AwaitingConfirmation'],
  edit_plan: ['Executing', 'AwaitingConfirmation', 'Answering', 'Complete', 'Partial', 'Limited', 'ObservedOnly'],
  retry_step: ['Partial'],
  cancel: RUN_STATUSES,
  viz_report: RUN_STATUSES,
} as const satisfies Record<Exclude<OrionActionName, 'ask' | 'warmup'>, readonly RunStatus[]>;

export interface UserMessage {
  id: string;
  role: 'user';
  content: string;
}

/** All seven fields are always present; tools and context stay empty. */
export interface RunAgentInput {
  threadId: string;
  runId: string;
  state: Record<string, never>;
  messages: UserMessage[];
  tools: [];
  context: [];
  forwardedProps: { orion: OrionAction };
}

// ------------------------------------------------------------- BFF routes

export const ORION_ROUTES = {
  agui: '/api/orion/agui',
  view: (runId: string) => `/api/orion/runs/${runId}/view`,
  record: (runId: string) => `/api/orion/runs/${runId}/record`,
} as const;

/** The headers the agui route answers a stream with. */
export const SSE_RESPONSE_HEADERS = {
  'Content-Type': 'text/event-stream; charset=utf-8',
  'Cache-Control': 'no-cache, no-transform',
  'X-Accel-Buffering': 'no',
} as const;

/** The Runtime session id is `orion-<threadId>`: AgentCore requires at least 33 characters. */
export const RUNTIME_SESSION_HEADER = 'X-Amzn-Bedrock-AgentCore-Runtime-Session-Id';
export const runtimeSessionId = (threadId: string): string => `orion-${threadId}`;

export type BffErrorCode =
  | 'INVALID_INPUT'
  | 'RUN_NOT_FOUND'
  | 'SESSION_BUSY'
  | 'UPSTREAM_ERROR'
  | 'UPSTREAM_UNAVAILABLE'
  | 'UPSTREAM_TIMEOUT';

/** The JSON body (never an event stream) of every BFF route error; the transport parses it. */
export interface BffError {
  error: { code: BffErrorCode; message: string };
}

/**
 * What the browser does with each BFF error (contract "Client handling of BFF errors"):
 * `reject` treats the turn as rejected; `pollView` polls the target run's view route until it
 * is not leased, then resends unchanged only if the run still waits for the action (an ask: only
 * if its view is 404); `checkView` reads the view of the turn's runId first (200: follow that run;
 * 404: rejected), never resending an ask under a new runId; `notStored` drops the run on restore.
 */
export const BFF_ERROR_HANDLING = {
  INVALID_INPUT: 'reject',
  SESSION_BUSY: 'pollView',
  UPSTREAM_ERROR: 'checkView',
  UPSTREAM_TIMEOUT: 'checkView',
  UPSTREAM_UNAVAILABLE: 'reject',
  RUN_NOT_FOUND: 'notStored',
} as const satisfies Record<BffErrorCode, 'reject' | 'pollView' | 'checkView' | 'notStored'>;

// ----------------------------------------- Run record (orion.run-record/v1)
// What GET /api/orion/runs/[runId]/record returns, unchanged from the store.

export type ToolStatus = 'ok' | 'empty' | 'error' | 'unavailable';
export type Transport = 'in_process' | 'gateway' | 'client';

export interface Provenance {
  method: 'GET' | 'POST';
  path: string;
  requestSha256: string;
  httpStatus: number | null;
  responseSha256: string | null;
  elapsedMs: number;
}

/**
 * One attempt of one counted call. `observed` is the full output the Evidence Inspector shows.
 * `callId` is `<runId>.v<planVersion>.<stepId>.c<n>`; an aborted attempt has status `error` and an
 * `error` starting "CANCELLED".
 */
export interface CallRecord {
  callId: string;
  planVersion: number;
  stepId: string;
  tool: string;
  transport: Transport;
  attempt: number;
  startedAt: string;
  request: JsonValue;
  requestSha256: string;
  httpStatus: number | null;
  responseSha256: string | null;
  elapsedMs: number;
  status: ToolStatus;
  observed: JsonValue;
  warnings: string[];
  limitation: OrionCode | null;
  error: string | null;
  provenance: Provenance[];
}

export interface ModelCallRecord {
  callId: string;
  role: 'planner' | 'composer';
  model: string;
  fallback: boolean;
  effort: 'low' | 'medium' | 'high';
  attempt: number;
  startedAt: string;
  elapsedMs: number;
  outcome: 'ok' | 'refused' | 'invalid' | 'error' | 'cancelled';
  stopReason: string | null;
  inputTokens: number | null;
  outputTokens: number | null;
  cacheReadTokens: number | null;
  cacheWriteTokens: number | null;
}

export interface FactRecord extends Fact {
  planVersion: number;
  callId: string;
  requestSha256: string;
  responseSha256: string;
  engine: string | null;
}

export interface CohortRef extends CohortView {
  definition: CanonicalDefinition | null;
}

export interface AnswerRecord {
  observed: Sentence[];
  limitations: Limitation[];
  interpretation: Sentence[] | null;
  hypotheses: Sentence[] | null;
  withheldReason: string | null;
  vizSpecs: VizSpec[];
  followUps: FollowUp[];
  openLinks: OpenLink[];
  notice: string;
}

export interface SupersededVersion {
  planVersion: number;
  at: string;
  status: RunStatus;
  steps: Step[];
  facts: FactRecord[];
  cohorts: CohortRef[];
  answer: AnswerRecord;
}

/** The planner's IR, snake_case as the planner writes it (orion_agent/ir.py). */
export type PlannerOutputRecord = { kind: 'plan' | 'clarify' | 'unsupported' } & { [key: string]: JsonValue };

export interface PlanHistoryEntry {
  version: number;
  cause: 'ask' | 'clarify_answer' | 'edit_plan';
  at: string;
  ir: PlannerOutputRecord | null;
  edit: (EditPlanAction & ActionBase) | null;
}

/** An IR clause: snake_case, values in stored spelling. */
export interface IrClause {
  field: string;
  op: 'in' | '=' | '!=' | '>' | '>=' | '<' | '<=';
  values: (string | number)[];
}

export interface CompiledStep {
  id: string;
  row: number;
  tool: string;
  kind: StepKind;
  folded: boolean;
  inputSummary: string;
  /** The step's exact arguments; a server tool sends them through its golden template. */
  args: { [key: string]: JsonValue };
  dependsOn: string[];
}

export interface CompiledPlan {
  version: number;
  signature: string;
  scope: PlanScope & { clauses: IrClause[] };
  rows: PlanRow[];
  steps: CompiledStep[];
  assumptions: Assumption[];
  limitations: Limitation[];
  writes: boolean;
  paraphrase: string;
  altScope: (PlanScope & { clauses: IrClause[] }) | null;
  altScopeChoice: ScopeChoice | null;
  editable: Editable[];
}

/** A voided nonce (an edit or a cancel replaced the pause) has decision null. */
export interface ConfirmationRecord {
  nonce: string;
  decision: 'create' | 'dont_save' | null;
  saved: SavedCohortReadBack[];
  makeActive: string | null;
  at: string;
  outcome: 'accepted' | 'verify_failed' | 'voided';
}

export interface VizReportRecord {
  vizId: string;
  mounted: boolean;
  error: string | null;
  pinnedHashVerified: boolean | null;
  at: string;
}

export interface ActionLogEntry {
  at: string;
  action: OrionActionName;
  outcome: 'accepted' | 'repeat' | 'rejected';
  code: OrionCode | null;
}

export interface LedgerUse {
  follows: string | null;
  refs: { runId: string; ref: string; name: string }[];
}

export interface Lease {
  owner: string;
  renewedAt: string;
  expiresAt: string;
}

export interface Environment {
  mode: 'L' | 'A' | 'H';
  planner: string;
  executor: string;
  agentVersion: string;
  toolTransport: Transport | null;
  fingerprintSha256: string | null;
  /** The ORION_FAULTS in force (`<target>:<kind>`, sorted); empty in a real run. */
  faults: string[];
}

export interface AskRecord {
  action: 'ask';
  question: string;
  cohortContext: CohortContext;
  vizReports: VizReport[];
  cancelWaiting: string | null;
}

export interface RunRecord {
  schema: 'orion.run-record/v1';
  threadId: string;
  runId: string;
  revision: number;
  status: RunStatus;
  code: OrionCode | null;
  question: string;
  createdAt: string;
  updatedAt: string;
  environment: Environment;
  /** Set only in a LEASED_STATUSES status. */
  lease: Lease | null;
  request: AskRecord;
  plannerOutput: PlannerOutputRecord | null;
  planVersions: CompiledPlan[];
  planHistory: PlanHistoryEntry[];
  modelCalls: ModelCallRecord[];
  steps: Step[];
  calls: CallRecord[];
  facts: FactRecord[];
  cohorts: CohortRef[];
  pending: Pending | null;
  confirmations: ConfirmationRecord[];
  vizReports: VizReportRecord[];
  actions: ActionLogEntry[];
  ledger: LedgerUse;
  answer: AnswerRecord;
  superseded: SupersededVersion[];
  /** The RunView as of the last transition, untrimmed: what the view route serves. */
  runView: RunView | null;
}
